from collections import deque,defaultdict
H,W=A.shape
comps=[]; seen=set()
for r in range(H):
 for c in range(W):
  col=A[r,c]
  if col==3 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   p=q.pop(); cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    v=(p[0]+dr,p[1]+dc)
    if 0<=v[0]<H and 0<=v[1]<W and v not in seen and A[v]==col:
     seen.add(v); q.append(v)
  comps.append((int(col),cells))
def norm(cells):
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 return frozenset((r-r0,c-c0) for r,c in cells)
for i,(col,cells) in enumerate(comps):
 shape=norm(cells)
 print(i,col,len(cells),(min(r for r,c in cells),min(c for r,c in cells)),(max(r for r,c in cells),max(c for r,c in cells)),sorted(shape))

def transforms(s):
 out=[]
 for k in range(4):
  pts=set(s)
  for _ in range(k): pts={(c,-r) for r,c in pts}
  for flip in [False,True]:
   p={(r,-c if flip else c) for r,c in pts}
   minr=min(r for r,c in p); minc=min(c for r,c in p)
   out.append(frozenset((r-minr,c-minc) for r,c in p))
 return set(out)
def contains_shape(big, small):
 # all placements within bbox and orientation
 b=set(big); maxr=max(r for r,c in b); maxc=max(c for r,c in b)
 for s in transforms(small):
  sr=max(r for r,c in s); sc=max(c for r,c in s)
  for dr in range(maxr-sr+1):
   for dc in range(maxc-sc+1):
    if {(r+dr,c+dc) for r,c in s}<=b: return True,(dr,dc,s)
 return False,None
for i,(col,cells) in enumerate(comps):
 print('component',i,'color',col,'matches in larger comps:',[(j,c2) for j,(c2,cells2) in enumerate(comps) if len(cells2)>len(cells) and (m:=contains_shape(norm(cells2),norm(cells)))[0]])
